import{_ as l,l as n,o as e,c as i,v as t,p as s,x as r,d as E,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"ESG 因子争论","description":"","frontmatter":{"title":"ESG 因子争论","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/esg-factor-debate.md","filePath":"quant/esg-factor-debate.md","lastUpdated":1789023840000}'),p={name:"quant/esg-factor-debate.md"};function c(m,a,u,b,B,_){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="esg-因子争论" tabindex="-1">ESG 因子争论 <a class="header-anchor" href="#esg-因子争论" aria-label="Permalink to &quot;ESG 因子争论&quot;">​</a></h1><div class="epigraph"><p>ESG 分数既可能是风险补偿、也可能是偏好导致的需求曲线，还可能只是数据供应商之间的噪声；三种机制要求三种完全不同的组合回应。</p><footer>—— Pástor, Stambaugh and Taylor, Journal of Financial Economics, 2021；分数分歧见 Berg, Kölbel and Rigobon</footer></div><p><a href="/quant/buyback-flows">上一课</a>把发行人买盘当成机械流。ESG 的缺口是<strong>另一类非现金流转的需求</strong>：委托、标签与基金章程把资本推向高分名字。金融栏有 ESG 理论，本课不重写伦理或福利。量化栏要决定：它是因子、是约束、还是数据。不要把绿色组合相对市场的超额再拿去跑一遍 <a href="/quant/capm">CAPM</a> 当「发现」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Pástor–Stambaugh–Taylor 与 Pedersen–Fitzgibbons–Pomorski 给出均衡语言：若投资人偏好可持续资产，高 ESG 的预期收益可以更低（已付更高价格），气候风险暴露则要求补偿。实证上两股力量对谁占上风随样本变。Berg–Kölbel–Rigobon 记录评级商之间的「加总混乱」：同一公司在不同供应商处分差极大，于是「ESG 因子」不可复现。问题是产品层必须先选机制：当风险因子就该进 <a href="/quant/fundamental-risk-model">基本面风险模型</a>；当偏好流就该当约束与拥挤；当噪声就不该进信号。</p><p>Hartzmark–Sussman 显示可持续标签引发资金流动。流可以制造短期超额，随后是更低的长期预期收益。这与被动纳入是同一类需求曲线，不是新的 HML。</p><h3 id="分数不是会计" tabindex="-1">分数不是会计 <a class="header-anchor" href="#分数不是会计" aria-label="Permalink to &quot;分数不是会计&quot;">​</a></h3><p>价值因子至少有账面、盈余等可复算投入。ESG 分数是供应商的黑盒加权。换商、换权重，多空组合几乎换一批名字。研究日志必须冻结供应商与版本，否则发表后的「失效」只是数据修订。</p><p><span class="marginnote">把排除清单（武器、煤炭）当成因子收益，会把行业赌注叫做 ESG alpha。应先行业中性，再看残差是否还值借券与跟踪误差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种用法分开回测：风险暴露（气候、争议事件）、偏好约束（跟踪误差最小化加排除）、分数动量（流的代理）。对照：换评级商的稳健性；相对价值、质量、低波动的正交。容量：标签基金的申赎与指数纳入同步时，拥挤与 ESG 流合一。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>偏好移动需求曲线；风险补偿移动供给价格；测量误差增加残差。短期内流可以主导，长期内若偏好持续，高分资产的折现率可以更低。策略若两边都想赚，会自我矛盾。</p>',13)),(e(),s(h,null,{default:r(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Score%5B%22ESG%20%E5%88%86%E6%95%B0%22%5D%20--%3E%20Noise%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E5%88%86%E6%AD%A7%22%5D%0A%20%20Pref%5B%22%E5%A7%94%E6%89%98%E4%B8%8E%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20Flow%5B%22%E9%9C%80%E6%B1%82%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20Risk%5B%22%E6%B0%94%E5%80%99%E7%AD%89%E9%A3%8E%E9%99%A9%22%5D%20--%3E%20Prem%5B%22%E8%A6%81%E6%B1%82%E8%A1%A5%E5%81%BF%22%5D%0A%20%20Flow%20--%3E%20Px%5B%22%E7%9F%AD%E6%9C%9F%E4%BB%B7%E6%A0%BC%20%E9%95%BF%E6%9C%9F%E9%A2%84%E6%9C%9F%E6%94%B6%E7%9B%8A%22%5D%0A%20%20Prem%20--%3E%20Px%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评判可持续投资的规范价值。监管披露与漂绿是法律与产品问题，不是回测调参对象。金融栏理论课此处只链接。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ESG 要先选机制：风险、偏好流、或噪声，不能三者一起当 alpha。</li><li>评级分歧使因子不可复现，必须冻结数据版本。</li><li>标签流与纳入流同类，先中性行业与质量。</li><li>出处：Pástor, Stambaugh and Taylor, <em>JFE</em>, 2021；Pedersen, Fitzgibbons and Pomorski；Berg, Kölbel and Rigobon 对评级分歧。</li></ul>',4))])}const S=l(p,[["render",c]]);export{A as __pageData,S as default};
